-- stochastic-processes implementation for ParticleFilter
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))

local Module = {}
function Module.SystematicResample(particles,weights,offset)
    assert(#particles==#weights and #particles>0,"particle/weight dimensions mismatch")
    local total=0; for _,w in ipairs(weights) do assert(w>=0,"particle weights must be nonnegative"); total+=w end
    Num.Positive(total,"total particle weight")
    local n=#particles; local start=(offset or 0.5)/n; assert(start>=0 and start<1/n,"systematic offset must be in [0,1/N)")
    local result=table.create(n); local c=weights[1]/total; local index=1
    for j=1,n do
        local u=start+(j-1)/n
        while u>c and index<n do index+=1; c+=weights[index]/total end
        result[j]=table.clone(particles[index])
    end
    return result
end

return Module
